import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np

sns.set_theme(style="darkgrid")

class ViewData:
 def __init__(self, path):
 self.path = path
 self.count = 0
 self.tal = []
 self.temp = []
 self.mmhg = []
 self.humd = []
 self.tin = []
 self.tout = []
 self.humdout = []
 self.pairs = {}

 def init_data(self):
 count = 0

 with open(self.path, "r", encoding="utf8") as file:
 for line in file:
 count += 1
 self.tal = [0]*count
 self.temp = [0]*count
 self.mmhg = [0]*count
 self.humd = [0]*count
 self.tin = [0]*count
 self.tout = [0]*count
 self.humdout = [0]*count

 def readNparseLog(self):
 self.init_data()
 count = -1
 with open(self.path, "r", encoding="utf8") as file:
 for line in file:
 count +=1
 # обрабатываешь одну строку
 ln = line.strip()
 for item in ln.split(","):
 key, value = item.split(":", 1) # 1 ограничивает количество разделений
 self.pairs[key.strip()] = value.strip()
 self.tal[count] = float(self.pairs.get('time after launch'))
 self.temp[count] = float(self.pairs.get('temp', 0))
 self.mmhg[count] = float(self.pairs.get('MmHg', 0))
 self.humd[count] = float(self.pairs.get('humd', 0))
 self.tin[count] = float(self.pairs.get('temp IN', 0))
 self.tout[count] = float(self.pairs.get('temp OUT', 0))
 self.humdout[count] = float(self.pairs.get('humd OUT', 0))

 def viewData(self):
 fig, axs = plt.subplots(2, 3, figsize=(12, 8))
 axs = axs.flatten()

 # График 1
 sns.lineplot(x=self.tal, y=self.temp, ax=axs[0], color="blue")
 axs[0].set_title("Температура")

 # График 2
 sns.lineplot(x=self.tal, y=self.mmhg, ax=axs[1], color="green")
 axs[1].set_title("Давление")

 # График 3
 sns.lineplot(x=self.tal, y=self.humd, ax=axs[2], color="red")
 axs[2].set_title("Влажность")

 # График 4
 sns.lineplot(x=self.tal, y=self.tin, ax=axs[3], color="orange")
 axs[3].set_title("Данные на выносном датчике")

 # График 5
 sns.lineplot(x=self.tal, y=self.tout, ax=axs[4], color="cyan")
 axs[4].set_title("Температура на улице")

 # График 6
 sns.lineplot(x=self.tal, y=self.humdout, ax=axs[5], color="purple")
 axs[5].set_title("Влажность на улице")

 plt.tight_layout()
 plt.show()

def main():
 print("Hello from viewdatams!")
 vd = ViewData("ESPstation_logs.txt")

 vd.readNparseLog()

 vd.viewData()

if __name__ == "__main__":
 main()
